SELECT ?s ?label ?tsid WHERE {
  ?s ref:hasLabel ?label .
  FILTER(?label="Perimeter_top_ZN_2")
  ?s ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsid .
}

SELECT ?s ?n WHERE {
  ?s a brick:Zone .
  ?s rdfs:label ?n .
} LIMIT 50

SELECT ?point ?pt ?tsid WHERE {
  ?point a ?pt .
  ?point brick:isPointOf ?zone .
  FILTER(?zone="http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z03")
  OPTIONAL{?point ref:hasTimeseriesId ?tsid}
}

SELECT ?zone ?point ?pt ?tsid WHERE {
  ?zone brick:hasPoint ?point .
  FILTER(?zone="http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z03")
  ?point a ?pt .
  OPTIONAL{?point ref:hasTimeseriesId ?tsid}
}

SELECT ?point ?pt ?tsid WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z03> brick:hasPoint ?point .
  ?point a ?pt .
  OPTIONAL{?point ref:hasTimeseriesId ?tsid}
}

SELECT ?child ?ct ?tsid WHERE {
  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z03.Occupancy_Sensor> ?p ?child .
  OPTIONAL{?child a ?ct}
  OPTIONAL{?child ref:hasTimeseriesId ?tsid}
}

